contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We call requestLoan (may or may not revert) and then attempt to clearRequest for the given reqID.
    // If clearRequest succeeds (does not revert) then the request with that id must be inactive afterwards.
    function run(uint256 reqAmount, uint256 reqInterest, uint256 reqL2C, uint256 reqDuration, uint256 clearReqID, bool repayDirect, bool isCallback) public payable {
        require(true);

        // Try to create a request from this contract. It may revert due to token transfers; capture that.
        bool reqReverted;
        c.requestLoan(reqAmount, reqInterest, reqL2C, reqDuration); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reqReverted = true;
        } else {
            reqReverted = false;
        }

        // Try to clear the request with id clearReqID. Capture whether it reverted.
        bool clearReverted;
        uint256 loanID = c.clearRequest(clearReqID, repayDirect, isCallback); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            clearReverted = true;
        } else {
            clearReverted = false;
        }

        // Observe isActive for the request id. If the call reverts (e.g., out-of-bounds), treat that as false conservatively.
        bool activeAfter;
        bool a = c.isActive(clearReqID); bool __rev2 = __ESBMC_reverted(); if (__rev2) {
            activeAfter = false;
        } else {
            activeAfter = a;
        }

        // General rule: If clearRequest did not revert, then isActive(clearReqID) must be false.
        assert(clearReverted || !activeAfter);
    }

    receive() external payable { }
}

