// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 reqAmount, uint256 reqInterest, uint256 reqL2C, uint256 reqDuration, uint256 clearReqID, bool repayDirect, bool isCallback) internal {
        vm.assume(true);
        bool reqReverted;
        try c.requestLoan(reqAmount, reqInterest, reqL2C, reqDuration) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }
        bool clearReverted;
        try c.clearRequest(clearReqID, repayDirect, isCallback) returns (uint256 loanID) {
            clearReverted = false;
        } catch {
            clearReverted = true;
        }
        bool activeAfter;
        try c.isActive(clearReqID) returns (bool a) {
            activeAfter = a;
        } catch {
            activeAfter = false;
        }
        assertTrue(clearReverted || !activeAfter);
    }

    function testFuzz_run(uint256 reqAmount, uint256 reqInterest, uint256 reqL2C, uint256 reqDuration, uint256 clearReqID, bool repayDirect, bool isCallback) public {
        _run(reqAmount, reqInterest, reqL2C, reqDuration, clearReqID, repayDirect, isCallback);
    }

    receive() external payable { }
}
